// Arma el cuerpo del envío. Peso fijo: cada paca son 100 lb / 45 kg.
// Si piden más de una, se multiplica.
const p = $json.body || {};
const faltan = ['orden_id', 'nombre', 'telefono', 'codigo_postal', 'sucursal_ocurre']
  .filter(k => !p[k]);
if (faltan.length) {
  return [{ json: { ok: false, motivo: 'faltan_datos', faltan } }];
}

const cantidad = Number(p.cantidad || 1);
return [{ json: {
  ok: true,
  orden_id: p.orden_id,
  contactId: p.contactId,
  envio: {
    origin: {
      name: $env.ALMACEN_NOMBRE,
      street: $env.ALMACEN_CALLE,
      number: $env.ALMACEN_NUMERO,
      district: $env.ALMACEN_COLONIA,
      city: $env.ALMACEN_CIUDAD,
      state: $env.ALMACEN_ESTADO,
      country: 'MX',
      postalCode: $env.ALMACEN_CP,
      phone: $env.ALMACEN_TELEFONO,
      email: $env.ALMACEN_EMAIL
    },
    destination: {
      name: p.nombre,
      phone: p.telefono,
      country: 'MX',
      postalCode: p.codigo_postal,
      city: p.ciudad,
      state: p.estado_mx,
      reference: p.sucursal_ocurre
    },
    packages: [{
      content: 'Ropa',
      amount: cantidad,
      type: 'box',
      weight: 45 * cantidad,
      weightUnit: 'KG',
      lengthUnit: 'CM',
      dimensions: { length: 60, width: 45, height: 45 }
    }],
    shipment: { carrier: 'paquetexpress', type: 1 },
    settings: { printFormat: 'PDF', printSize: 'STOCK_4X6', comments: `Orden ${p.orden_id}` }
  }
} }];

// Saca el número de rastreo y la etiqueta de la respuesta.
const r = $json.data || $json;
const primero = Array.isArray(r) ? r[0] : r;
const guia = primero.trackingNumber || primero.tracking_number;
const etiqueta = primero.label || primero.trackUrl || primero.labelUrl;
const previo = $('Armar el envío').first().json;

if (!guia) {
  return [{ json: { ok: false, motivo: 'envia_sin_guia', respuesta: primero, orden_id: previo.orden_id } }];
}
return [{ json: { ok: true, orden_id: previo.orden_id, contactId: previo.contactId,
                  numero_guia: guia, etiqueta_pdf: etiqueta,
                  fecha_envio: new Date().toISOString() } }];
